insert into tb_special_image (special_image_id, image_id, special_id, 
  status, delete_flag, create_by, 
  create_time, update_by, update_time
  )
values (#{specialImageId,jdbcType=BIGINT}, #{imageId,jdbcType=BIGINT}, #{specialId,jdbcType=BIGINT}, 
  #{status,jdbcType=SMALLINT}, #{deleteFlag,jdbcType=SMALLINT}, #{createBy,jdbcType=BIGINT}, 
  #{createTime,jdbcType=TIMESTAMP}, #{updateBy,jdbcType=BIGINT}, #{updateTime,jdbcType=TIMESTAMP}
  )

mapper.select:
SELECT p.image_id, p.thumb_url, p.image_url, p.image_code, p.create_time, p.image_name, p.special_image_id
FROM ( SELECT t1.thumb_url, t1.image_url, t1.image_code, t1.create_time, t1.image_id, t1.image_name, (SELECT t2.special_image_id FROM tb_special_image t2 WHERE t2.image_id = t1.image_id AND t2.special_id = #{belongSpecialId} ) special_image_id FROM tb_image t1
AND t1.topic_name like concat('%', #{topicName}, '%')
AND t1.topic_id = #{topicId}
AND t1.status = #{status}
AND t1.create_by = #{createBy}
AND t1.delete_flag = #{deleteFlag}
) p
AND p.image_name like concat('%', #{imageName}, '%')
AND p.image_code like concat('%', #{imageCode}, '%')
AND p.special_image_id IS NOT NULL
AND p.special_image_id IS NULL
AND date_format(p.create_time,'%y%m%d') >= date_format(#{createTimeParams.beginTime},'%y%m%d')
AND date_format(p.create_time,'%y%m%d') <= date_format(#{createTimeParams.endTime},'%y%m%d')
ORDER BY p.create_time desc

SELECT t1.topic_id FROM tb_image t1 WHERE t1.image_id IN ( SELECT min( t2.image_id ) FROM tb_special_image t2
where t2.special_id = #{specialId}
)

SELECT t1.special_image_id, t1.image_id, t1.special_id, t1.slice_image_status, t1.audit_status, t1.edit_by, t1.delivery_status, t1.topic_id, t1.slice_batch_number, t2.image_name, t2.topic_name, t2.image_code, t2.image_path, t2.image_url, t2.thumb_url, t1.`status`, t1.delete_flag, t1.create_time, t1.create_by, t1.update_by, t1.update_time, t2.host_id FROM tb_special_image t1 LEFT JOIN tb_image t2 ON t1.image_id = t2.image_id
AND t2.image_code like concat('%', #{imageCode}, '%')
AND t2.image_name like concat('%', #{imageName}, '%')
AND t1.special_image_id = #{specialImageId}
AND t1.special_id = #{belongSpecialId}
AND t1.special_id = #{specialId}
AND t1.special_image_id in
#{specialImageId}
AND date_format(t1.create_time,'%y%m%d') >= date_format(#{createTimeParams.beginTime},'%y%m%d')
AND date_format(t1.create_time,'%y%m%d') <= date_format(#{createTimeParams.endTime},'%y%m%d')
ORDER BY t1.create_time desc

SELECT t1.special_image_id, t1.special_id, t2.thumb_url, t2.image_url, t2.image_name, t2.image_code, t1.image_id, t1.slice_batch_number, t1.slice_image_status, t1.audit_status, t1.audit_time, t1.edit_by, t3.nick_name FROM tb_special_image t1 LEFT JOIN tb_image t2 ON t1.image_id = t2.image_id LEFT JOIN sys_user t3 ON t1.edit_by = t3.user_id
AND t2.image_code like concat('%', #{imageCode}, '%')
AND t2.image_name like concat('%', #{imageName}, '%')
AND t1.slice_image_status = #{sliceImageStatus}
AND t1.audit_status = #{auditStatus}
AND t1.special_image_id IN ( SELECT p1.special_image_id FROM tb_sub_image p1 LEFT JOIN tb_special_image p2 ON p1.special_image_id = p2.special_image_id WHERE p1.slice_batch_number = p2.slice_batch_number AND p1.special_id = #{belongSpecialId}
AND p1.image_name LIKE concat('%',#{newImageName},'%')
)
AND t1.image_id IN ( SELECT t3.parent_image_id FROM tb_sub_image t3 WHERE
AND t3.image_code like concat('%', #{newImageCode}, '%')
)
AND t1.special_id = #{belongSpecialId}
AND t1.special_image_id IN ( select DISTINCT(t6.special_image_id) from tb_algorithm_special_image t6 where t6.algorithm_uuid = '20230811_anno' and t6.`status` in (2,3) )
AND date_format(t1.audit_time,'%y%m%d') >= date_format(#{createTimeParams.beginTime},'%y%m%d')
AND date_format(t1.audit_time,'%y%m%d') <= date_format(#{createTimeParams.endTime},'%y%m%d')
ORDER BY t1.create_time DESC

